export function TechLogo({
  skill,
  className = "h-6 w-6",
  fallbackTextClassName = "text-[10px]",
}: {
  skill: SkillTag;
  className?: string;
  fallbackTextClassName?: string;
}) {
  const icon = skill.icon ? iconMap[skill.icon] : undefined;
  const extra = !icon && skill.icon ? extraIconMap[skill.icon] : undefined;

  if (icon) {
    return (
      <svg
        viewBox="0 0 24 24"
        className={className}
        fill={skill.monochrome ? "currentColor" : `#${icon.hex}`}
      >
        <path d={icon.path} />
      </svg>
    );
  }

  if (extra) {
    return (
      <svg
        viewBox={extra.viewBox}
        className={className}
        fill={skill.monochrome ? "currentColor" : (skill.color ?? "currentColor")}
      >
        <path d={extra.path} />
      </svg>
    );
  }

  return (
    <span
      className={`flex h-full w-full items-center justify-center rounded-md font-bold text-white ${fallbackTextClassName}`}
      style={{ background: skill.color ?? "var(--color-accent)" }}
    >
      {skill.abbr}
    </span>
  );
}

export function TechIcon({ skill }: { skill: SkillTag }) {
  const [hovered, setHovered] = useState(false);

  return (
    <div
      className="relative flex flex-col items-center"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocus={() => setHovered(true)}
      onBlur={() => setHovered(false)}
      tabIndex={0}
    >
      <span
        role="tooltip"
        className={`absolute -top-9 z-20 whitespace-nowrap rounded-md border border-line bg-panel-alt px-2 py-1 text-[11px] font-semibold tracking-wide text-ink shadow-sm transition-opacity duration-150 ${
          hovered ? "opacity-100" : "pointer-events-none opacity-0"
        }`}
      >
        {skill.name.toUpperCase()}
      </span>
      <div
        className={`text-ink-soft flex h-11 w-11 items-center justify-center rounded-xl border border-line bg-tech-icon-bg p-2 transition-colors duration-150 hover:border-accent/40 ${
          skill.monochrome ? "hover:text-accent" : ""
        }`}
      >
        <TechLogo skill={skill} />
      </div>
    </div>
  );
}
